import json
from copy import deepcopy

def assign(houses, pos, attr, value):
    # Ensure uniqueness across houses for Name, Mother, Pet
    current = houses[pos][attr]
    if current is not None and current != value:
        return False
    # Uniqueness check: value should not appear in any other house for this attribute
    for i in range(len(houses)):
        if i != pos and houses[i][attr] == value:
            return False
    houses[pos][attr] = value
    return True

def pos_of(houses, attr, value):
    for i, h in enumerate(houses):
        if h[attr] == value:
            return i
    return None

def check_all_constraints(houses):
    # Uniqueness checks
    for attr in ['Name', 'Mother', 'Pet']:
        vals = [h[attr] for h in houses]
        if any(v is None for v in vals):
            return False
        if len(set(vals)) != len(vals):
            return False

    # Clue checks
    # 1. Bob is not in the second house.
    if houses[1]['Name'] == 'Bob':
        return False

    # 2. Two houses between cat and rabbit.
    if abs(pos_of(houses, 'Pet', 'cat') - pos_of(houses, 'Pet', 'rabbit')) != 3:
        return False

    # 3. Cat is directly left of Holly.
    if pos_of(houses, 'Pet', 'cat') + 1 != pos_of(houses, 'Mother', 'Holly'):
        return False

    # 4. Hamster directly left of rabbit.
    if pos_of(houses, 'Pet', 'hamster') + 1 != pos_of(houses, 'Pet', 'rabbit'):
        return False

    # 5. Rabbit is Eric.
    if pos_of(houses, 'Pet', 'rabbit') != pos_of(houses, 'Name', 'Eric'):
        return False

    # 6. One house between dog and cat.
    if abs(pos_of(houses, 'Pet', 'dog') - pos_of(houses, 'Pet', 'cat')) != 2:
        return False

    # 7. Cat is Janelle.
    if pos_of(houses, 'Pet', 'cat') != pos_of(houses, 'Mother', 'Janelle'):
        return False

    # 8. Alice directly left of Carol.
    if pos_of(houses, 'Name', 'Alice') + 1 != pos_of(houses, 'Name', 'Carol'):
        return False

    # 9. Carol is Aniya.
    if pos_of(houses, 'Name', 'Carol') != pos_of(houses, 'Mother', 'Aniya'):
        return False

    # 10. Arnold has a cat.
    if pos_of(houses, 'Name', 'Arnold') != pos_of(houses, 'Pet', 'cat'):
        return False

    # 11. Kailyn is rabbit.
    if pos_of(houses, 'Mother', 'Kailyn') != pos_of(houses, 'Pet', 'rabbit'):
        return False

    # 12. Fish is Sarah.
    if pos_of(houses, 'Pet', 'fish') != pos_of(houses, 'Mother', 'Sarah'):
        return False

    return True

def solve():
    # Setup
    names = ['Arnold', 'Eric', 'Bob', 'Alice', 'Carol', 'Peter']
    mothers = ['Sarah', 'Holly', 'Janelle', 'Aniya', 'Penny', 'Kailyn']
    pets = ['hamster', 'dog', 'bird', 'cat', 'fish', 'rabbit']

    base = [{'House': i+1, 'Name': None, 'Mother': None, 'Pet': None} for i in range(6)]

    # Begin constructive search using strong constraints
    for Apos in range(5):  # Arnold with cat; needs a Holly to the right
        h1 = deepcopy(base)
        if not assign(h1, Apos, 'Name', 'Arnold'):
            continue
        if not assign(h1, Apos, 'Pet', 'cat'):
            continue
        if not assign(h1, Apos, 'Mother', 'Janelle'):  # Clue 7 + 10
            continue

        posHolly = Apos + 1
        if posHolly > 5:
            continue
        if not assign(h1, posHolly, 'Mother', 'Holly'):  # Clue 3
            continue

        candidate_Rpos = []
        for r in [Apos + 3, Apos - 3]:  # Clue 2
            if 0 <= r <= 5:
                candidate_Rpos.append(r)

        for Rpos in candidate_Rpos:
            h2 = deepcopy(h1)
            # Rabbit, Eric, Kailyn
            if not assign(h2, Rpos, 'Pet', 'rabbit'):
                continue
            if not assign(h2, Rpos, 'Name', 'Eric'):
                continue
            if not assign(h2, Rpos, 'Mother', 'Kailyn'):
                continue

            # Hamster directly left of rabbit (Clue 4)
            Hpos = Rpos - 1
            if Hpos < 0:
                continue
            if not assign(h2, Hpos, 'Pet', 'hamster'):
                continue

            # Enforce clue 2 explicitly
            if abs(Rpos - Apos) != 3:
                continue

            # Dog one house between dog and cat (Clue 6)
            d_candidates = []
            for d in [Apos - 2, Apos + 2]:
                if 0 <= d <= 5:
                    d_candidates.append(d)

            for Dpos in d_candidates:
                if Dpos in [Apos, Rpos, Hpos]:
                    continue
                h3 = deepcopy(h2)
                if not assign(h3, Dpos, 'Pet', 'dog'):
                    continue
                if abs(Dpos - Apos) != 2:
                    continue

                # Alice directly left of Carol, and Carol is Aniya (Clues 8, 9)
                for Cpos in range(6):
                    if Cpos < 1:
                        continue
                    AlicesPos = Cpos - 1
                    h4 = deepcopy(h3)
                    if not assign(h4, Cpos, 'Name', 'Carol'):
                        continue
                    if not assign(h4, Cpos, 'Mother', 'Aniya'):
                        continue
                    if not assign(h4, AlicesPos, 'Name', 'Alice'):
                        continue

                    # Remaining pets are bird and fish
                    rem_positions = [i for i in range(6) if h4[i]['Pet'] is None]
                    if len(rem_positions) != 2:
                        continue

                    for p_order in [(rem_positions[0], 'fish', rem_positions[1], 'bird'),
                                    (rem_positions[0], 'bird', rem_positions[1], 'fish')]:
                        h5 = deepcopy(h4)
                        if not assign(h5, p_order[0], 'Pet', p_order[1]):
                            continue
                        if not assign(h5, p_order[2], 'Pet', p_order[3]):
                            continue

                        # Fish with Sarah (Clue 12)
                        fish_pos = pos_of(h5, 'Pet', 'fish')
                        if fish_pos is None:
                            continue
                        if not assign(h5, fish_pos, 'Mother', 'Sarah'):
                            continue

                        # Assign the last remaining mother (Penny)
                        remaining_mother_positions = [i for i in range(6) if h5[i]['Mother'] is None]
                        if len(remaining_mother_positions) != 1:
                            continue
                        if not assign(h5, remaining_mother_positions[0], 'Mother', 'Penny'):
                            continue

                        # Assign remaining names Bob and Peter with Bob not in second house (Clue 1)
                        rem_name_positions = [i for i in range(6) if h5[i]['Name'] is None]
                        if len(rem_name_positions) != 2:
                            continue
                        for bob_pos in rem_name_positions:
                            if bob_pos == 1:
                                continue
                            h6 = deepcopy(h5)
                            other_pos = rem_name_positions[0] if rem_name_positions[1] == bob_pos else rem_name_positions[1]
                            if not assign(h6, bob_pos, 'Name', 'Bob'):
                                continue
                            if not assign(h6, other_pos, 'Name', 'Peter'):
                                continue

                            if check_all_constraints(h6):
                                return h6
    return None

def main():
    solution = solve()
    if solution is None:
        output = {
            "solution": {
                "header": ["House", "Name", "Mother", "Pet"],
                "rows": []
            }
        }
    else:
        header = ["House", "Name", "Mother", "Pet"]
        rows = []
        for i in range(6):
            rows.append([str(solution[i]["House"]), solution[i]["Name"], solution[i]["Mother"], solution[i]["Pet"]])
        output = {
            "solution": {
                "header": header,
                "rows": rows
            }
        }
    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    main()
